$string['guidehotspotbody'] = '<p>A hotspot question asks a student to click directly on the slide to answer - e.g. "Where is Meckel\'s cartilage?" - instead of choosing from a written list. They find out right away whether they clicked in the right place.</p><p><strong>To set one up</strong>: choose the "Image with a short question below" layout - hotspot questions only work with this layout. A new <strong>Hotspot question</strong> dropdown appears: choose <strong>Single region</strong> (one correct spot) or <strong>Multiple regions</strong> (any one of several correct spots counts - useful when the same feature appears more than once on the slide). A small drawing toolbar appears on the live preview - draw the correct region (or regions) directly on the slide. This region is never sent to a student\'s browser before they click - only whether their own click was right or wrong.</p><p>Once a region is drawn, you can fine-tune it: drag the round white handle above it to <strong>rotate</strong> it to match an angled feature, or drag any of the 4 square white corners to <strong>resize</strong> it - both stay centred on where you originally drew it. For multiple regions, click a region first to select it (needed for "Delete region" too) - the handles only ever show for whichever one is currently selected.</p><p>Write your question in the text box below the slide, same as any other layout.</p>';
$string['guidehotspotheading'] = 'Hotspot questions';
$string['guidehotspotimagea'] = 'The Layout section with "Image with a short question below" selected and the Hotspot question dropdown visible.';
$string['guidehotspotimageb'] = 'The drawing toolbar mid-use on the live preview - an actual region being drawn, not an empty/idle toolbar.';
$string['guidehotspotimagec'] = 'A student-facing hotspot question after clicking - the right/wrong feedback actually visible.';
$string['guidehotspotimaged'] = 'A drawn region selected, showing the round rotate handle above it and the 4 square resize handles at its corners, mid-rotation.';
$string['guidehotspotqtypenote'] = 'There\'s also a separate, fuller Moodle quiz question type for graded hotspot questions inside a real Moodle quiz - a different, deeper integration than the standalone embed hotspot covered above. Ask whoever manages your Moodle\'s plugins if you want graded quiz hotspots.';
$string['guideintro'] = 'This is for anyone with editing rights in a course who wants to embed an OMERO microscopy slide, with your own commentary alongside it - no HTML or URLs to type by hand.';
$string['guidelink'] = 'New to this? Read the visual guide';
$string['guidestep0body'] = 'Go into your course. Look at the row of tabs near the top (Course, Participants, Grades...) and click <strong>"More"</strong> - a dropdown opens. Click <strong>"Embed an OMERO slide"</strong>. If you don\'t see it there, you don\'t have editing rights in this particular course, or it hasn\'t been enabled yet - ask whoever manages your Moodle\'s plugins.';
$string['guidestep0heading'] = 'Finding the tool';
$string['guidestep0image'] = 'The course "More" dropdown open, "Embed an OMERO slide" visible/highlighted.';
$string['guidestep1body'] = '<strong>Subject account</strong> - a dropdown. Pick whichever matches the department or subject area your slide belongs to. Don\'t see one yet? Click "Manage your OMERO connections" to add your own - entirely self-service. <strong>Image ID</strong> - the OMERO image ID of the slide you want. <strong>Dataset ID (optional)</strong> - only if you want students to browse between images in the same dataset. Then click <strong>Load slide</strong>.';
$string['guidestep1heading'] = 'Load a slide';
$string['guidestep1image'] = 'The load-slide row, with the Subject account dropdown and Image ID field visible (a subject already selected reads better than the empty state).';
$string['guidestep2body'] = 'Three real choices: slide and text side by side (either order), or slide only with no write-up box at all. Switching between them later is completely safe - nothing you\'ve already written is ever lost.';
$string['guidestep2heading'] = 'Choose a layout';
$string['guidestep2image'] = 'The layout radios, with a real slide already loaded behind them.';
$string['guidestep3body'] = 'Type your write-up as normal. Pan/zoom the slide to something worth pointing out. Select the relevant word or phrase in your text, then click <strong>Insert view link</strong>. That text becomes clickable - a student who clicks it jumps the slide to exactly that view. Repeat as many times as you like, even on the same image.';
$string['guidestep3heading'] = 'Write your text and add view-links';
$string['guidestep3imagea'] = 'A word selected in the write-up text, next to the "Insert view link" button.';
$string['guidestep3imageb'] = 'The same text immediately after clicking "Insert view link" - now visibly a link.';
$string['guidestep4body'] = 'Different from a view-link - this is what the embed shows before anyone clicks anything. Pan/zoom to the position you want, then click <strong>Set as opening view</strong>. Skip this step and the embed just opens showing the whole slide at its default zoom.';
$string['guidestep4heading'] = 'Set the opening view (optional)';
$string['guidestep4image'] = 'The "Set as opening view" button.';
$string['guidestep5body'] = 'Click <strong>Generate embed HTML</strong>, then <strong>Copy to clipboard</strong>. Go to wherever you want the slide to appear - a Label, a Page, a Lesson content page, anything with Moodle\'s normal text editor. Before pasting, switch that editor to its <strong>Source code</strong> view (in the editor toolbar: <strong>View &gt; Source code</strong>) - pasting directly into the normal view will not work, since what you copied is real HTML, not formatted text, and the editor will escape or strip it. Paste into the source code box, then switch back and save. Students see the slide and your write-up exactly as you built them.';
$string['guidestep5heading'] = 'Generate and paste';
$string['guidestep5image'] = 'The Generate/Copy buttons, with a real generated embed preview visible underneath.';
