$string['viewheatmaplink'] = 'View heatmap';
$string['viewingoptionsheading'] = 'Viewing options';
$string['viewlinkbuttons'] = 'Insert view link vs. Set opening view';
$string['viewlinkbuttons_help'] = '<p><strong>Insert view link</strong> turns selected text in your write-up into a clickable link - when a student clicks it later, the slide jumps to exactly the pan/zoom position you had set up at the moment you clicked the button. Select some text first, then click.</p><p><strong>Set as opening view</strong> is different: it\'s what the embed shows before anyone clicks anything at all, the very first thing a student sees. It doesn\'t insert anything into your text, and doesn\'t need any text selected - just pan/zoom to where you want it to start, then click.</p><p>You can use both, either, or neither - they don\'t affect each other.</p>';
$string['widthdesc'] = 'Match this to the actual content width of a course page/label/book in your Moodle theme, so the view you pick here looks right once pasted there - the default is measured from this site\'s own content column, but themes vary.';
$string['widthlabel'] = 'Width';
$string['writeupplaceholder'] = 'Enter your write-up here.';
